<template>
 <aside class="scenario-panel" :class="{inline}" aria-label="事件与AI处置">
  <header><div><span class="eyebrow">事件与决策</span><h3>{{ s.weather?.title || '大棚运行中' }}</h3></div><span class="scenario-label">模拟</span></header>
  <div class="automation"><label><input type="checkbox" :checked="s.autoEvents" :disabled="busy||s.pending" @change="configure('autoEvents',$event)" />自动事件</label><label><input type="checkbox" :checked="s.autoActuation" :disabled="busy||s.pending" @change="configure('autoActuation',$event)" />AI自动处置</label></div>
  <div class="trigger-row"><select v-model="eventType" aria-label="选择事件" :disabled="busy||s.pending"><option v-for="e in events" :key="e.code" :value="e.code">{{ e.label }}</option></select><button :disabled="busy||s.pending||!!s.weather&&eventType!=='FAULT'" @click="command('trigger',{type:eventType})">触发事件</button><button v-if="s.weather" :disabled="busy||s.pending" @click="command('endWeather',{})">结束天气</button></div>
  <p v-if="error" class="scenario-error" role="status">{{ error }}</p>
  <p v-if="s.weather" class="event-window">{{ s.weather.startedAt.slice(5,16).replace('T',' ') }} 至 {{ s.weather.endsAt.slice(5,16).replace('T',' ') }} · 雨势 {{ s.environment.rainMmH.toFixed(1) }} mm/h · 风 {{ s.environment.windMps.toFixed(1) }} m/s</p>
  <section class="decision-section"><div class="section-title"><h4>AI 处置</h4><span :class="{'analyzing':s.pending}">{{ statusLabel }}</span></div>
   <p v-if="s.pending" class="pending-message">正在读取事件、环境与设备。数据时钟暂候，画面保留当前状态。</p>
   <p v-if="s.decision.error" class="scenario-error">{{ s.decision.error }}</p>
   <template v-if="s.decision.plan"><AnswerBody :text="s.decision.plan.summary" :citations="s.decision.plan.references" @cite="citation=$event" /><details class="reason-details"><summary>判断依据</summary><p class="decision-reason">{{ s.decision.plan.reason }}</p></details>
    <div v-if="s.decision.plan.actions.length" class="action-list"><div v-for="a in s.decision.plan.actions" :key="a.device"><span>{{ deviceName(a.device) }}</span><b>{{ a.duty>0?'目标 '+Math.round(a.duty*100)+'%':'关闭' }}</b><small>{{ a.durationSteps*0.5 }} h</small></div></div>
    <p class="check-condition"><strong>观察</strong>{{ s.decision.plan.expected }}<br />{{ s.decision.plan.check }}</p>
    <details v-if="s.decision.plan.references.length"><summary>{{ s.decision.plan.references.length }} 条参考来源</summary><a v-for="source in s.decision.plan.references" :key="source.number" :href="safeUrl(source.url)" target="_blank" rel="noopener noreferrer" :class="{'selected-source':citation===source.number}">[{{ source.number }}] {{ source.title }}</a></details>
   </template>
   <p v-else-if="!s.pending" class="quiet">事件发生后，助手会结合当前环境制定方案。也可以主动请求分析。</p>
   <p v-if="s.decision.constraints?.length" class="scenario-error">{{ s.decision.constraints.join('；') }}</p>
   <div class="ai-actions"><button :disabled="busy||s.pending" @click="command('decide',{question:'请分析当前环境与事件，给出仿真处置方案并观察反馈',apply:true})">{{ s.decision.plan?'重新判断':'让 AI 处理' }}</button><button @click="openChat">与助手讨论 ↗</button></div>
  </section>
  <section class="scenario-feedback"><div class="section-title"><h4>处理反馈</h4><small>模型对照</small></div><div ref="chartRef" class="feedback-chart"></div>
   <p v-if="s.decision.feedback">与同事件未干预计算相比：温度差 {{ s.decision.feedback.temperatureDifferenceC.toFixed(1) }}°C，湿度差 {{ s.decision.feedback.humidityDifferencePct.toFixed(1) }} 个百分点。</p><p v-else class="quiet">设备开启后继续计算环境，风险按持续时间判断。</p>
  </section>
  <details class="device-details"><summary>设备状态与健康</summary><div v-for="(healthy,code) in s.deviceHealth" :key="code" class="device-row"><span>{{ deviceName(String(code)) }}</span><small>{{ healthy?(s.devices[code]?'运行 '+Math.round(s.deviceDuty[code]*100)+'%':'关闭'):'模拟故障' }}</small><button v-if="!healthy" :disabled="s.pending||busy" @click="command('repair',{device:code})">模拟恢复</button></div></details>
  <details class="timeline" open><summary>最近过程</summary><ol><li v-for="(item,i) in s.timeline.slice(-5).reverse()" :key="item.at+item.type+i"><time>{{ item.at.slice(11,16) }}</time><span>{{ item.message }}</span></li></ol></details>
  <details class="source-note"><summary>来源与计算条件</summary><p v-for="note in s.assumptions" :key="note">{{ note }}</p><p>{{ s.actionEffects }}</p><details v-if="s.parameters?.length"><summary>未校准的响应参数</summary><p v-for="p in s.parameters" :key="p.name">{{ p.name }}：{{ p.value }} {{ p.unit }}（项目工程假设）</p></details><p>随机种子 {{ s.seed }}；模型版本 {{ s.responseModelVersion }}。</p></details>
 </aside>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue';
import {useRouter} from 'vue-router';
import * as echarts from 'echarts';
import {commandM3Scenario,getM3Live,type M3LiveRun} from '/@/api/m3/live';
import AnswerBody from '/@/components/agent/AnswerBody.vue';
const props=defineProps<{run:M3LiveRun;inline?:boolean}>(),emit=defineEmits<{(e:'change',run:M3LiveRun):void}>();
const s=computed(()=>props.run.current.scenario!),router=useRouter(),busy=ref(false),error=ref(''),eventType=ref('STORM'),citation=ref(0),chartRef=ref<HTMLDivElement>();
const events=[{code:'STORM',label:'暴雨'},{code:'COLD_SNAP',label:'骤降温'},{code:'HEAT_WAVE',label:'热浪'},{code:'STRONG_WIND',label:'强风'},{code:'OVERCAST',label:'连续阴雨'},{code:'NIGHT_HUMIDITY',label:'夜间高湿'},{code:'FAULT',label:'设备故障'}];
const labels:Record<string,string>={HEATING:'加热',IRRIGATION:'滴灌',VENTILATION:'侧窗',SUPPLEMENTAL_LIGHT:'补光',SHADE:'遮阳',CO2_SUPPLY:'CO₂施用',ROOF_VENT:'屋窗',EXHAUST_FAN:'排风',COOLING_PAD:'湿帘',CIRCULATION_FAN:'环流风机'};
const deviceName=(c:string)=>labels[c]||c;
const statusLabel=computed(()=>({IDLE:'等待事件',NEEDS_DECISION:'待分析',ANALYZING:'分析中',OBSERVING:'已应用，观察中',PROPOSED:'方案未执行',MITIGATED:'环境风险已缓解',UNRESOLVED:'风险仍存在',BLOCKED:'动作被约束拦截',FAILED:'请求失败',STALE:'方案过期'} as Record<string,string>)[s.value.decision.status]||s.value.decision.status);
let timer:ReturnType<typeof setTimeout>|undefined,chart:echarts.ECharts|undefined,observer:ResizeObserver|undefined,disposed=false;
function safeUrl(url:string){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:undefined;}catch{return undefined;}}
async function command(operation:string,input:unknown){busy.value=true;error.value='';try{const value=await commandM3Scenario(props.run.runId,operation,input);if(!disposed)emit('change',value);}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
function configure(key:'autoEvents'|'autoActuation',event:Event){void command('configure',{autoEvents:s.value.autoEvents,autoActuation:s.value.autoActuation,[key]:(event.target as HTMLInputElement).checked});}
function openChat(){router.push({path:'/agentChat',query:{liveRun:props.run.runId}});}
function poll(){timer=setTimeout(async()=>{if(disposed)return;try{let value=await getM3Live(props.run.runId,true);if(props.inline&&value.cursor>props.run.cursor)value=await getM3Live(props.run.runId);if(!disposed)emit('change',value);}catch(e){error.value=e instanceof Error?e.message:String(e);}if(!disposed)poll();},2000);}
function draw(){if(!chartRef.value)return;if(!observer){observer=new ResizeObserver(()=>{if(chart)chart.resize();else draw();});observer.observe(chartRef.value);}if(!chartRef.value.clientWidth||!chartRef.value.clientHeight)return;if(!chart){chart=echarts.init(chartRef.value);}const rows=s.value.trends.slice(-30);chart.setOption({animation:false,color:['#647e52','#b4aa8e'],legend:{top:0,textStyle:{fontSize:11,color:'#8e967d'},itemWidth:13,itemHeight:5},grid:{left:30,right:10,top:30,bottom:22},tooltip:{trigger:'axis'},xAxis:{type:'category',data:rows.map(r=>r.at.slice(11,16)),axisLabel:{fontSize:11,color:'#9eaa8e'},axisTick:{show:false}},yAxis:{type:'value',name:'°C',nameTextStyle:{fontSize:11},axisLabel:{fontSize:11,color:'#9eaa8e'},splitLine:{lineStyle:{color:'#e6e8da'}}},series:[{name:'当前处理',type:'line',showSymbol:false,data:rows.map(r=>Number(r.temperatureC.toFixed(1)))},{name:'未干预推演',type:'line',showSymbol:false,lineStyle:{type:'dashed',width:1.5},data:rows.map(r=>Number(r.shadowTemperatureC.toFixed(1)))}]},true);}
watch(()=>[props.run.runId,s.value.tick,s.value.decision.status],()=>nextTick(draw));onMounted(()=>{poll();void nextTick(draw);});onBeforeUnmount(()=>{disposed=true;if(timer)clearTimeout(timer);observer?.disconnect();chart?.dispose();});
</script>
<style scoped>
.scenario-panel{position:absolute;right:20px;top:112px;width:350px;max-height:calc(100% - 155px);overflow:auto;z-index:9;padding:20px;background:rgba(255,253,245,.97);color:#45543e;border:1px solid #dedfce;box-shadow:0 12px 35px #303b2420;scrollbar-width:thin}.scenario-panel header{display:flex;align-items:center;justify-content:space-between}.eyebrow{font-size:12px;letter-spacing:1.5px;color:#9aa184}h3{font-size:20px;font-weight:500;margin:6px 0 0}.scenario-label{font-size:12px;color:#8c9d75;border:1px solid #d9dfce;padding:4px 7px}.automation{display:flex;gap:20px;font-size:12px;color:#7f8f6b;margin:18px 0 12px}.automation label{display:flex;align-items:center;gap:5px;cursor:pointer}.automation input{accent-color:#647d52}.trigger-row{display:flex;gap:6px;flex-wrap:wrap}.scenario-panel select,.scenario-panel button{font:inherit;font-size:12px;padding:6px 8px;background:#f7f7ee;color:#708363;border:1px solid #dce1ce;cursor:pointer}.scenario-panel button:hover{background:#e9eedf}.scenario-panel button:disabled{opacity:.45;cursor:default}.scenario-panel button:focus-visible{outline:2px solid #698859;outline-offset:2px}.scenario-error{font-size:12px;color:#a5744e;background:#f4eadd;padding:9px;line-height:1.7}.event-window{font-size:12px;line-height:1.8;color:#a19f88}.decision-section,.scenario-feedback{border-top:1px solid #dee3d1;margin-top:17px;padding-top:15px}.section-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.section-title h4{font-size:14px;font-weight:500;margin:0}.section-title span,.section-title small{font-size:12px;color:#8b9a73}.analyzing{animation:breathe 1.4s infinite}.pending-message,.quiet{font-size:13px;line-height:1.8;color:#959c83}.decision-section :deep(.answer-body){font-size:14px;line-height:1.85}.decision-reason{font-size:12px;line-height:1.8;color:#8d997c}.action-list{margin:13px 0}.action-list>div{display:grid;grid-template-columns:1fr auto 45px;gap:9px;padding:7px 0;border-bottom:1px solid #e9ecdf;font-size:12px}.action-list b{font-weight:500;color:#668254}.action-list small{text-align:right;color:#a0aa8e;font-size:12px}.check-condition{font-size:12px;line-height:1.8;color:#8c997a}.check-condition strong{font-weight:500;color:#728960;margin-right:10px}.scenario-panel details{font-size:12px;margin-top:13px;color:#94a07e}.scenario-panel summary{cursor:pointer;padding:5px 0}.scenario-panel details a{display:block;font-size:12px;line-height:1.8;padding:7px 0;color:#7d9466;text-decoration:none}.selected-source{background:#e9eedc}.ai-actions{display:flex;gap:8px;margin-top:12px}.ai-actions button:first-child{background:#687e55;color:#fff;border-color:#687e55}.feedback-chart{height:150px;width:100%}.scenario-feedback p{font-size:12px;line-height:1.8;color:#9aa386}.device-row{display:flex;justify-content:space-between;gap:8px;padding:8px 0;border-bottom:1px solid #e8ecdb}.device-row small{font-size:12px}.device-row button{padding:2px 4px;font-size:12px}.timeline ol{list-style:none;padding:0}.timeline li{display:grid;grid-template-columns:36px 1fr;gap:9px;font-size:12px;line-height:1.9;margin:9px 0}.timeline time{color:#acb397;font-variant-numeric:tabular-nums}.source-note p{font-size:12px;line-height:1.8}.source-note{border-top:1px solid #e4e8d6;padding-top:7px}@keyframes breathe{50%{opacity:.45}}@media(prefers-reduced-motion:reduce){.analyzing{animation:none}}@media(max-width:1050px){.scenario-panel{width:300px;right:12px}}@media(max-width:780px){.scenario-panel{position:relative;right:auto;top:auto;width:auto;max-height:550px;margin:10px}}
</style>
